//! The clean tier's skater and board.
//!
//! The skater is a CC0 MakeHuman character with our own body shape, rig names and animation set,
//! generated by `scripts/cleanroom/blender/make_skater.py` (clips authored in `skater_anims.py`)
//! into `assets/skater.glb`. Every clip is driven by hand each frame: its time comes from the
//! engine's state (crouch, push phase, flip progress, time since the pop or landing) and its weight
//! from the mode, eased so transitions blend. The board is built in code.
use super::sim::CleanSkate;
use bevy::prelude::*;
use skate_lite_sys::{EventKind, Mode, State};
use std::f32::consts::FRAC_PI_2;


pub(crate) use super::board::{DECK_CENTRE, DECK_TOP};
use super::board::{TRUCK_Z, WHEEL_R};
/// Grabs that turn the deck (skater_anims.py METHOD_ROLL / ROCKET_PITCH, degrees).
pub(crate) const METHOD_ROLL: f32 = 38.0;
pub(crate) const ROCKET_PITCH: f32 = 42.0;
/// Ankle height above the sole in the authored clips.
pub(crate) const ANKLE: f32 = 0.075;
/// Where the pop clip reaches its full extension (the flip clips start from that pose).
const POP_TOP_AT: f32 = 0.1;
/// Tail snap on the pop: peak nose-up pitch (radians), when it peaks and when it is level again.
const POP_PITCH: f32 = 0.34;
const POP_PITCH_PEAK: f32 = 0.05;
const POP_PITCH_END: f32 = 0.24;

const SKATER_GLB: &str = "embedded://skate_game/clean/assets/skater.glb";

/// Clips in the order of [`CLIP_NAMES`].
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(usize)]
enum Clip {
    Ride,
    Crouch,
    Pop,
    Air,
    FlipKick,
    FlipHeel,
    FlipShuv,
    Land,
    Push,
    Manual,
    ManualNose,
    Grind,
    Boardslide,
    Powerslide,
    Bail,
    StepOn,
    // One per grab style, in sk8_grab_style order (style n is GRAB_FIRST + n - 1).
    GrabIndy,
    GrabCrail,
    GrabTail,
    GrabStalefish,
    GrabMelon,
    GrabNose,
    GrabTuckKnee,
    GrabJudo,
    GrabDouble,
    GrabSuperman,
    GrabNoFoot,
    GrabStiffy,
    PopNollie,
    FlipHard,
    FlipTre,
    Grind50,
    StepOff,
    PushMongo,
    StepOffMongo,
    StepOnMongo,
    GrabChrist,
    GrabMethod,
    GrabRocket,
    PopNoComply,
    PopBoneless,
    GrindNose,
    GrindCrooked,
    GrindOvercrook,
    GrindSmith,
    GrindFeeble,
    SlideNose,
    SlideTail,
    SlideLip,
    SlideNoseblunt,
    SlideBlunt,
    Wallride,
    Stand,
    Walk,
    Run,
}

const CLIPS: usize = 55;
const GRAB_FIRST: usize = Clip::GrabIndy as usize;
pub(crate) const CLIP_NAMES: [&str; CLIPS] = [
    "sk8_ride", "sk8_crouch", "sk8_pop", "sk8_air", "sk8_flip_kick", "sk8_flip_heel", "sk8_flip_shuv", "sk8_land", "sk8_push", "sk8_manual",
    "sk8_nose_manual", "sk8_grind", "sk8_boardslide", "sk8_powerslide", "sk8_bail", "sk8_push_end",
    "sk8_grab_indy", "sk8_grab_crail", "sk8_grab_tail", "sk8_grab_stalefish", "sk8_grab_melon", "sk8_grab_nose",
    "sk8_grab_tuck_knee", "sk8_grab_judo", "sk8_grab_double", "sk8_grab_superman", "sk8_grab_no_foot", "sk8_grab_stiffy",
    "sk8_pop_nollie", "sk8_flip_hard", "sk8_flip_tre", "sk8_grind_5_0", "sk8_push_start", "sk8_push_mongo",
    "sk8_push_start_mongo", "sk8_push_end_mongo", "sk8_grab_christ", "sk8_grab_method", "sk8_grab_rocket",
    "sk8_pop_no_comply", "sk8_pop_boneless",
    "sk8_grind_nose", "sk8_grind_crooked", "sk8_grind_overcrook", "sk8_grind_smith", "sk8_grind_feeble", "sk8_slide_nose", "sk8_slide_tail", "sk8_slide_lip", "sk8_slide_noseblunt", "sk8_slide_blunt", "sk8_wallride",
    "sk8_stand", "sk8_walk", "sk8_run",
];
/// Clips that loop (idles and the push); the rest play once and hold their last frame.
const LOOPED: [Clip; 24] = [
    Clip::Wallride,
    Clip::Stand,
    Clip::Walk,
    Clip::Run,
    Clip::GrindNose,
    Clip::GrindCrooked,
    Clip::GrindOvercrook,
    Clip::GrindSmith,
    Clip::GrindFeeble,
    Clip::SlideNose,
    Clip::SlideTail,
    Clip::SlideLip,
    Clip::SlideNoseblunt,
    Clip::SlideBlunt,

    Clip::Ride,
    Clip::Crouch,
    Clip::Push,
    Clip::PushMongo,
    Clip::Manual,
    Clip::ManualNose,
    Clip::Grind,
    Clip::Grind50,
    Clip::Boardslide,
    Clip::Powerslide,
];

#[derive(Component)]
pub(crate) struct RiderRoot;
#[derive(Component)]
pub(crate) struct BoardRoot;

#[derive(Resource)]
pub(crate) struct Avatar {
    gltf: Handle<Gltf>,
    nodes: Option<Vec<AnimationNodeIndex>>,
    player: Option<Entity>,
    /// Each clip's length as exported (s), so timing follows the authored clips.
    lens: [f32; CLIPS],
    pub(crate) bones: Option<super::procedural::Bones>,
    pub(crate) weights: [f32; CLIPS],
    weight_vel: [f32; CLIPS],
    /// Each clip's time; a clip fading out holds where it was instead of jumping to its start.
    pub(crate) times: [f32; CLIPS],
}

pub(crate) fn spawn(
    mut commands: Commands,
    assets: Res<AssetServer>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut materials: ResMut<Assets<StandardMaterial>>,
) {
    let rider = commands
        .spawn((RiderRoot, Transform::default(), Visibility::default()))
        .id();
    // The clips face -Y in Blender (= +Z here) with the nose along +X; the engine's
    // board has its nose along +Z, so the character turns a quarter about Y.
    let scene = commands
        .spawn((
            SceneRoot(assets.load(GltfAssetLabel::Scene(0).from_asset(SKATER_GLB))),
            Transform::from_rotation(Quat::from_rotation_y(-FRAC_PI_2)),
        ))
        .id();
    commands.entity(rider).add_child(scene);
    commands.insert_resource(Avatar {
        gltf: assets.load(SKATER_GLB),
        nodes: None,
        player: None,
        lens: [1.0; CLIPS],
        bones: None,
        weights: [0.0; CLIPS],
        weight_vel: [0.0; CLIPS],
        times: [0.0; CLIPS],
    });

    // Board: root at the deck centre so flips turn about it.
    let board = commands.spawn((BoardRoot, Transform::default(), Visibility::default())).id();
    super::board::build(&mut commands, board, &mut meshes, &mut materials);
}

/// Once the glTF is in: one animation graph with every clip, on the scene's player.
pub(crate) fn bind(
    mut commands: Commands,
    mut avatar: ResMut<Avatar>,
    gltfs: Res<Assets<Gltf>>,
    anims: Res<Assets<AnimationClip>>,
    mut graphs: ResMut<Assets<AnimationGraph>>,
    mut materials: ResMut<Assets<StandardMaterial>>,
    players: Query<Entity, Added<AnimationPlayer>>,
    names: Query<(Entity, &Name)>,
) {
    if avatar.nodes.is_some() {
        return;
    }
    let (Some(gltf), Ok(player)) = (gltfs.get(&avatar.gltf), players.single()) else { return };
    let clips: Vec<Handle<AnimationClip>> = CLIP_NAMES
        .iter()
        .map(|n| gltf.named_animations.get(*n).cloned().unwrap_or_else(|| {
            warn!("SK8 avatar: clip {n} missing");
            Handle::default()
        }))
        .collect();
    for (len, clip) in avatar.lens.iter_mut().zip(&clips) {
        if let Some(c) = anims.get(clip) {
            *len = c.duration().max(1e-3);
        }
    }
    let (graph, nodes) = AnimationGraph::from_clips(clips);
    // MakeHuman materials arrive alpha-blended, which sorts badly (skin shows through the
    // clothes); cut-out alpha keeps hair and lashes and draws everything else opaque.
    for handle in &gltf.materials {
        if let Some(m) = materials.get_mut(handle) {
            m.alpha_mode = AlphaMode::Mask(0.5);
        }
    }
    commands.entity(player).insert(AnimationGraphHandle(graphs.add(graph)));
    avatar.bones = super::procedural::Bones::find(&names);
    if avatar.bones.is_none() {
        warn!("SK8 avatar: bones for the procedural layer missing");
    }
    info!("SK8 avatar bound: {} clips, lengths {:?}", nodes.len(), avatar.lens);
    avatar.nodes = Some(nodes);
    avatar.player = Some(player);
}

#[derive(Resource)]
pub(crate) struct Clock {
    pub(crate) since_pop: f32,
    since_land: f32,
    since_grab: f32,
    /// Since the last kick ended (the back foot steps back on and the front foot turns back).
    since_push: f32,
    /// The last pop was off the nose (from the pop event's trick name).
    pub(crate) nollie: bool,
    /// The last pop was old school (no comply / boneless): its own pop clip, played through.
    old_school: Option<Clip>,
    /// The last pop was a hippie jump: the board stays on the ground, rolling on underneath.
    pub(crate) hippie: bool,
    /// Drives the idle loops (ride sway, manual and grind balance).
    idle: f32,
    /// Metres walked (on foot, the step cycle follows it).
    stride: f32,
}

impl Default for Clock {
    fn default() -> Self {
        // Long ago, so nothing plays its "just happened" clip at spawn.
        Self { since_pop: 9.0, since_land: 9.0, since_grab: 0.0, since_push: 9.0, nollie: false, old_school: None, hippie: false, idle: 0.0, stride: 0.0 }
    }
}

/// Which way the feet leave the board for this trick.
fn flip_clip(trick: &str) -> Clip {
    let t = trick.to_ascii_lowercase();
    // the board wraps round the back foot: both feet up and out of its way
    if t.contains("impossible") {
        Clip::FlipShuv
    } else if t.contains("hardflip") {
        Clip::FlipHard
    } else if t.contains("tre") || t.contains("laser") {
        Clip::FlipTre
    } else if t.contains("heel") {
        Clip::FlipHeel
    } else if t.contains("flip") {
        Clip::FlipKick
    } else {
        Clip::FlipShuv
    }
}

/// The old-school pops play their own clip.
fn old_school_clip(trick: &str) -> Option<Clip> {
    let t = trick.to_ascii_lowercase();
    if t.contains("no comply") {
        Some(Clip::PopNoComply)
    } else if t.contains("boneless") {
        Some(Clip::PopBoneless)
    } else {
        None
    }
}

/// Nollies pop off the nose.
pub(crate) fn is_nollie(trick: &str) -> bool {
    trick.to_ascii_lowercase().starts_with("nollie")
}

/// How long a blend into this clip takes (smoothing time of a critically damped follow, s):
/// the pop and catch are quick, body shifts like settling into a push or a manual slower.
fn blend_time(clip: Clip) -> f32 {
    match clip {
        Clip::Pop | Clip::PopNollie => 0.035,
        // the front foot steps down off the board: a little time to get there
        Clip::PopNoComply | Clip::PopBoneless => 0.06,
        Clip::FlipKick | Clip::FlipHeel | Clip::FlipShuv | Clip::FlipHard | Clip::FlipTre => 0.05,
        Clip::Land | Clip::Bail => 0.06,
        Clip::Air | Clip::Grind | Clip::Grind50 | Clip::Boardslide | Clip::Wallride => 0.1,
        // stepping off / walking speeds blend over a moment
        Clip::Stand | Clip::Walk | Clip::Run => 0.18,
        Clip::GrindNose | Clip::GrindCrooked | Clip::GrindOvercrook | Clip::GrindSmith | Clip::GrindFeeble | Clip::SlideNose | Clip::SlideTail | Clip::SlideLip | Clip::SlideNoseblunt | Clip::SlideBlunt => 0.1,
        Clip::GrabIndy
        | Clip::GrabCrail
        | Clip::GrabTail
        | Clip::GrabStalefish
        | Clip::GrabMelon
        | Clip::GrabNose
        | Clip::GrabTuckKnee
        | Clip::GrabJudo
        | Clip::GrabDouble
        | Clip::GrabSuperman
        | Clip::GrabNoFoot
        | Clip::GrabStiffy
        | Clip::GrabChrist
        | Clip::GrabMethod

        | Clip::Manual | Clip::ManualNose | Clip::Powerslide => 0.13,
        Clip::Ride | Clip::Crouch => 0.16,
        // both arms cross to the nose: given time, so the back arm doesn't whip round
        Clip::GrabRocket => 0.18,
        // The step-off clips do the turn to face down the board themselves.
        Clip::StepOff | Clip::StepOffMongo => 0.06,
        // Into a stroke from anything else (a landing, a powerslide): the body turns, not in a snap.
        Clip::Push | Clip::PushMongo => 0.16,
        Clip::StepOn | Clip::StepOnMongo => 0.1,
    }
}

/// (target weight, time) per clip for this state; `None` time = the clip is not playing.
fn targets(s: &State, c: &Clock, trick: &str, len: &[f32; CLIPS]) -> [(f32, Option<f32>); CLIPS] {
    let mut t = [(0.0, None); CLIPS];
    let mut set = |clip: Clip, w: f32, time: f32| {
        let l = len[clip as usize];
        let time = if LOOPED.contains(&clip) { time.rem_euclid(l) } else { time.clamp(0.0, l) };
        t[clip as usize] = (w, Some(time));
    };
    let pop_len = len[Clip::Pop as usize];
    match s.mode {
        Mode::Bail => set(Clip::Bail, 1.0, s.bail_time.unwrap_or(0.0)),
        Mode::Wallride => set(Clip::Wallride, 1.0, c.idle),
        // on foot: standing, walking or running by speed, the steps kept to the ground's pace
        Mode::Walk => {
            let walk = ((s.speed - 0.2) / 0.6).clamp(0.0, 1.0);
            let run = ((s.speed - 2.2) / 0.9).clamp(0.0, 1.0);
            set(Clip::Stand, 1.0 - walk, c.idle);
            set(Clip::Walk, walk * (1.0 - run), c.stride / 1.437);
            set(Clip::Run, walk * run, c.stride / 3.7);
        }
        Mode::Grind if s.grind_kind == 2 => set(Clip::Boardslide, 1.0, c.idle),
        Mode::Grind if s.grind_kind == 4 => set(Clip::Grind50, 1.0, c.idle),
        // sk8_grind_kind 5..14, in order
        Mode::Grind if (5..=14).contains(&s.grind_kind) => {
            const KINDS: [Clip; 10] = [Clip::GrindNose, Clip::GrindCrooked, Clip::GrindOvercrook, Clip::GrindSmith, Clip::GrindFeeble, Clip::SlideNose, Clip::SlideTail, Clip::SlideLip, Clip::SlideNoseblunt, Clip::SlideBlunt];
            set(KINDS[s.grind_kind as usize - 5], 1.0, c.idle)
        }
        Mode::Grind => set(Clip::Grind, 1.0, c.idle),
        Mode::Manual if s.manual_dir < 0 => set(Clip::ManualNose, 1.0, c.idle),
        Mode::Manual => set(Clip::Manual, 1.0, c.idle),
        Mode::Slide => set(Clip::Powerslide, 1.0, c.idle),
        Mode::Air => {
            // A flip or a grab takes over from the pop at full extension (a grab's reach then plays
            // from its start instead of the pose snapping to a grab already half done).
            let pop_until = if s.flip_progress.is_some() || s.grab != 0 { POP_TOP_AT } else { pop_len };
            if let Some(old) = c.old_school.filter(|clip| c.since_pop < len[*clip as usize] && s.grab == 0) {
                // the foot steps off and back on over the whole clip, a 180 turning the board under it
                set(old, 1.0, c.since_pop);
            } else if c.since_pop < pop_until {
                set(if c.nollie { Clip::PopNollie } else { Clip::Pop }, 1.0, c.since_pop);
            } else if let Some(p) = s.flip_progress {
                let clip = flip_clip(trick);
                set(clip, 1.0, p * len[clip as usize]);
            } else if s.grab != 0 {
                // The engine's grab style picks the clip; an unknown one falls back by hand.
                let style = match s.grab_style as usize {
                    n @ 1..=15 => n,
                    _ if s.grab == 3 => 9,
                    _ if s.grab & 1 != 0 => 5,
                    _ => 1,
                };
                let clip = match style {
                    13 => Clip::GrabChrist,
                    14 => Clip::GrabMethod,
                    15 => Clip::GrabRocket,
                    n => CLIP_ORDER[GRAB_FIRST + n - 1],
                };
                // from its first frame once it takes over at the pop's top (pressed earlier, it
                // would come in half way through its reach)
                set(clip, 1.0, c.since_grab.min((c.since_pop - POP_TOP_AT).max(0.0)));
            } else {
                // Tuck, hold, then reach the legs down for the landing.
                set(Clip::Air, 1.0, c.since_pop - pop_len);
            }
        }
        // a revert: weight back over the wheels as the board slides round (the powerslide's lean)
        Mode::Ride if s.revert.is_some() => set(Clip::Powerslide, 1.0, c.idle),
        Mode::Ride => {
            if c.since_land < len[Clip::Land as usize] {
                set(Clip::Land, 1.0, c.since_land);
            } else if let Some(k) = s.push_start {
                let clip = if s.push_mongo { Clip::StepOffMongo } else { Clip::StepOff };
                set(clip, 1.0, k * len[clip as usize]);
            } else if let Some(phase) = s.push_phase {
                let clip = if s.push_mongo { Clip::PushMongo } else { Clip::Push };
                set(clip, 1.0, phase * len[clip as usize]);
            } else if c.since_push < len[Clip::StepOn as usize] {
                let clip = if s.push_mongo { Clip::StepOnMongo } else { Clip::StepOn };
                set(clip, 1.0, c.since_push);
            } else if s.foot_off {
                // old school: the front foot steps down off the board onto the ground as the
                // crouch loads (the no comply's first pose), ready to spring off it at the pop
                let k = s.crouch.max(0.5);
                set(Clip::Ride, 1.0 - k, c.idle);
                set(Clip::PopNoComply, k, 0.0);
            } else {
                set(Clip::Ride, 1.0 - s.crouch, c.idle);
                set(Clip::Crouch, s.crouch, c.idle);
            }
        }
    }
    t
}

#[allow(clippy::type_complexity)]
pub(crate) fn animate(
    time: Res<Time<Real>>,
    sim: Res<CleanSkate>,
    mut avatar: ResMut<Avatar>,
    mut clock: ResMut<Clock>,
    mut players: Query<&mut AnimationPlayer>,
    mut rider: Query<&mut Transform, With<RiderRoot>>,
) {
    let dt = time.delta_secs().min(0.1);
    let (a, b, t) = (&sim.previous, &sim.current, sim.alpha());
    let pos = Vec3::from_array(a.position).lerp(Vec3::from_array(b.position), t);
    let rider_rot = Quat::from_array(a.rider_rot).slerp(Quat::from_array(b.rider_rot), t);
    let up = rider_rot * Vec3::Y;

    let game_dt = if sim.paused { 0.0 } else { dt * sim.time_scale };
    clock.since_pop += game_dt;
    clock.since_land += game_dt;
    clock.since_push = if b.push_phase.is_some() { 0.0 } else { clock.since_push + game_dt };
    clock.since_grab = if b.grab != 0 { clock.since_grab + game_dt } else { 0.0 };
    // The idles quicken a little with speed.
    clock.idle += game_dt * (0.7 + 0.3 * (b.speed / 6.0).min(1.0));
    clock.stride += game_dt * b.speed;
    for e in &sim.events {
        match e.kind {
            EventKind::Pop => {
                clock.since_pop = 0.0;
                clock.nollie = is_nollie(&e.name);
                clock.old_school = old_school_clip(&e.name);
                clock.hippie = e.name.to_ascii_lowercase().contains("hippie");
            }
            EventKind::Land => clock.since_land = 0.0,
            _ => {}
        }
    }

    let rider_at = pos + up * DECK_TOP;
    if let Ok(mut tf) = rider.single_mut() {
        *tf = Transform::from_translation(rider_at).with_rotation(rider_rot);
    }

    // Clip weights and times. Every weight follows its goal with a critically damped spring (eased
    // in and out, never overshooting), all at the pace of the clip being blended in.
    let goals = targets(b, &clock, &sim.rider.trick(), &avatar.lens);
    let lead = (0..CLIPS).max_by(|&i, &j| goals[i].0.total_cmp(&goals[j].0)).unwrap_or(0);
    let mut smooth = blend_time(CLIP_ORDER[lead]);
    // Popping straight out of a push: the body still faces down the board and must turn back to the
    // side, which in the pop's quick blend whips the whole torso round.
    let pushing: f32 = [Clip::Push, Clip::StepOn, Clip::StepOff, Clip::PushMongo, Clip::StepOffMongo, Clip::StepOnMongo]
        .iter()
        .map(|c| avatar.weights[*c as usize])
        .sum();
    if matches!(CLIP_ORDER[lead], Clip::Pop | Clip::PopNollie) && pushing > 0.05 {
        smooth = smooth.max(0.12);
    }
    // Landing before a flip's clip has finished (a held flick's last turn): the feet come down out
    // of the flip pose over a moment, not in the landing's quick snap.
    let flipping: f32 = [Clip::FlipKick, Clip::FlipHeel, Clip::FlipShuv, Clip::FlipHard, Clip::FlipTre]
        .iter()
        .map(|c| avatar.weights[*c as usize])
        .sum();
    if CLIP_ORDER[lead] == Clip::Land && flipping > 0.3 {
        smooth = smooth.max(0.1);
    }
    // A respawn is a cut: no standing up out of the bail in front of the camera.
    if sim.events.iter().any(|e| e.kind == EventKind::Respawn) {
        for i in 0..CLIPS {
            avatar.weights[i] = goals[i].0;
            avatar.weight_vel[i] = 0.0;
        }
    }
    for i in 0..CLIPS {
        let (mut w, mut v) = smooth_cd(avatar.weights[i], avatar.weight_vel[i], goals[i].0, smooth, dt);
        // A clip on its way out that's nearly gone leaves quickly: three clips at once (a push
        // still fading under a pop and a grab) blended an arm the long way round.
        if goals[i].0 == 0.0 && w < 0.15 && dt > 0.0 {
            w *= (-dt / 0.02).exp();
            v = 0.0;
        }
        avatar.weights[i] = w.clamp(0.0, 1.0);
        avatar.weight_vel[i] = v;
        if let Some(time) = goals[i].1 {
            avatar.times[i] = time;
        }
    }
    let total: f32 = avatar.weights.iter().sum::<f32>().max(1e-4);
    if let (Some(nodes), Some(player)) = (avatar.nodes.clone(), avatar.player) {
        if let Ok(mut player) = players.get_mut(player) {
            for (i, node) in nodes.iter().enumerate() {
                let weight = avatar.weights[i] / total;
                if !player.is_playing_animation(*node) {
                    player.play(*node).pause();
                }
                if let Some(active) = player.animation_mut(*node) {
                    active.set_weight(weight);
                    if weight > 1e-3 {
                        active.seek_to(avatar.times[i]);
                    }
                }
            }
        }
    }
}

/// The pop's tail snap: the tail slams down and the nose comes up, pivoting on the tail wheels,
/// then the front foot levels it out. Returns the board's shift and its turned rotation.
pub(crate) fn pop_snap(deck: Quat, since_pop: f32, nollie: bool) -> (Vec3, Quat) {
    if since_pop >= POP_PITCH_END {
        return (Vec3::ZERO, deck);
    }
    let k = if since_pop < POP_PITCH_PEAK {
        smooth01(since_pop / POP_PITCH_PEAK)
    } else {
        1.0 - smooth01((since_pop - POP_PITCH_PEAK) / (POP_PITCH_END - POP_PITCH_PEAK))
    };
    // A nollie snaps the nose down and pivots on the front wheels instead.
    let end = if nollie { 1.0 } else { -1.0 };
    let pitch = Quat::from_rotation_x(end * POP_PITCH * k);
    let pivot = Vec3::new(0.0, WHEEL_R - DECK_CENTRE, end * TRUCK_Z);
    (deck * (pivot - pitch * pivot), deck * pitch)
}

const CLIP_ORDER: [Clip; CLIPS] = [
    Clip::Ride, Clip::Crouch, Clip::Pop, Clip::Air, Clip::FlipKick, Clip::FlipHeel, Clip::FlipShuv, Clip::Land, Clip::Push,
    Clip::Manual, Clip::ManualNose, Clip::Grind, Clip::Boardslide, Clip::Powerslide, Clip::Bail, Clip::StepOn,
    Clip::GrabIndy, Clip::GrabCrail, Clip::GrabTail, Clip::GrabStalefish, Clip::GrabMelon, Clip::GrabNose, Clip::GrabTuckKnee,
    Clip::GrabJudo, Clip::GrabDouble, Clip::GrabSuperman, Clip::GrabNoFoot, Clip::GrabStiffy, Clip::PopNollie,
    Clip::FlipHard, Clip::FlipTre, Clip::Grind50, Clip::StepOff, Clip::PushMongo, Clip::StepOffMongo, Clip::StepOnMongo,
    Clip::GrabChrist, Clip::GrabMethod, Clip::GrabRocket, Clip::PopNoComply, Clip::PopBoneless,
    Clip::GrindNose, Clip::GrindCrooked, Clip::GrindOvercrook, Clip::GrindSmith, Clip::GrindFeeble, Clip::SlideNose, Clip::SlideTail, Clip::SlideLip, Clip::SlideNoseblunt, Clip::SlideBlunt, Clip::Wallride,
    Clip::Stand, Clip::Walk, Clip::Run,
];

pub(crate) fn smooth01(x: f32) -> f32 {
    let x = x.clamp(0.0, 1.0);
    x * x * (3.0 - 2.0 * x)
}

/// One step of a critically damped follow of `target` (smoothing time `smooth`, s): stable for
/// any frame time, so the blends look the same at 60, 72 or 90 Hz.
pub(crate) fn smooth_cd(value: f32, vel: f32, target: f32, smooth: f32, dt: f32) -> (f32, f32) {
    let omega = 2.0 / smooth.max(1e-3);
    let x = omega * dt;
    let decay = 1.0 / (1.0 + x + 0.48 * x * x + 0.235 * x * x * x);
    let change = value - target;
    let temp = (vel + omega * change) * dt;
    ((target + (change + temp) * decay), (vel - omega * temp) * decay)
}
